import{_ as a,c as e,o as t,a0 as r}from"./chunks/framework.DKRgXLPU.js";const n=JSON.parse('{"title":"Introduktion till mentalspelet - deltagarguide","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/sv/participant-guide.md","filePath":"public/downloads/sv/participant-guide.md"}');const i=a({name:"public/downloads/sv/participant-guide.md"},[["render",function(a,n,i,l,s,o){return t(),e("div",null,[...n[0]||(n[0]=[r('<h1 id="introduktion-till-mentalspelet-deltagarguide" tabindex="-1">Introduktion till mentalspelet - deltagarguide <a class="header-anchor" href="#introduktion-till-mentalspelet-deltagarguide" aria-label="Permalink to &quot;Introduktion till mentalspelet - deltagarguide&quot;">​</a></h1><p><strong>Petanque Academy</strong><em>Utveckling av elitspelare</em></p><hr><h2 id="valkomna" tabindex="-1">Välkomna <a class="header-anchor" href="#valkomna" aria-label="Permalink to &quot;Välkomna&quot;">​</a></h2><p>Idag lär du dig praktiska mentala speltekniker för att förbättra din bouleprestanda.</p><h3 id="vad-du-kommer-att-lara-dig" tabindex="-1">Vad du kommer att lära dig <a class="header-anchor" href="#vad-du-kommer-att-lara-dig" aria-label="Permalink to &quot;Vad du kommer att lära dig&quot;">​</a></h3><ul><li>Varför mental träning är viktig för elitspelare</li><li>Skillnaden mellan &quot;tekniskt läge&quot; och &quot;flödesläge&quot;</li><li>Hur man känner igen och hanterar sin inre kritiker</li><li>Enkla tekniker för tryckhantering</li><li>En grundläggande rutin före skotttagning</li></ul><hr><h2 id="zon-flodestillstandet" tabindex="-1">Zon-/flödestillståndet <a class="header-anchor" href="#zon-flodestillstandet" aria-label="Permalink to &quot;Zon-/flödestillståndet&quot;">​</a></h2><h3 id="vad-ar-flode" tabindex="-1">Vad är flöde? <a class="header-anchor" href="#vad-ar-flode" aria-label="Permalink to &quot;Vad är flöde?&quot;">​</a></h3><p>Flöde är det magiska tillståndet där:</p><ul><li>Allt känns obehindrat</li><li>Tiden verkar sakta ner</li><li>Du tänker inte, bara leker</li><li>Din teknik fungerar perfekt</li></ul><h3 id="tva-sinneslagen" tabindex="-1">Två sinneslägen <a class="header-anchor" href="#tva-sinneslagen" aria-label="Permalink to &quot;Två sinneslägen&quot;">​</a></h3><p><strong>Planeringsläge (analytiskt)</strong></p><ul><li>Analysera terrängen</li><li>Att välja din strategi</li><li>Att bestämma sig för skottet</li><li>Bedömning av risker</li></ul><p><strong>Utförandeläge (flöde)</strong></p><ul><li>Att lita på sin kropp</li><li>Tänker inte på tekniken</li><li>Fokus i nuet</li><li>Automatisk körning</li></ul><h3 id="vaxeln" tabindex="-1">Växeln <a class="header-anchor" href="#vaxeln" aria-label="Permalink to &quot;Växeln&quot;">​</a></h3><p>Den viktigaste färdigheten: <strong>växling från planerings- till utförandeläge</strong></p><p><strong>Före fotograferingen:</strong> Analysera, planera, besluta <strong>Under inspelningen:</strong> Tillit, flyt, genomföra</p><hr><h2 id="den-inre-kritikern-kontra-den-inre-coachen" tabindex="-1">Den inre kritikern kontra den inre coachen <a class="header-anchor" href="#den-inre-kritikern-kontra-den-inre-coachen" aria-label="Permalink to &quot;Den inre kritikern kontra den inre coachen&quot;">​</a></h2><h3 id="din-inre-kritiker-sager" tabindex="-1">Din inre kritiker säger: <a class="header-anchor" href="#din-inre-kritiker-sager" aria-label="Permalink to &quot;Din inre kritiker säger:&quot;">​</a></h3><ul><li>&quot;Det var hemskt!&quot;</li><li>&quot;Du gör alltid fel under press&quot;</li><li>&quot;Alla ser dig misslyckas&quot;</li><li>&quot;Du är inte tillräckligt bra&quot;</li></ul><h3 id="din-inre-coach-sager" tabindex="-1">Din inre coach säger: <a class="header-anchor" href="#din-inre-coach-sager" aria-label="Permalink to &quot;Din inre coach säger:&quot;">​</a></h3><ul><li>&quot;Vad kan jag lära mig av detta?&quot;</li><li>&quot;Nästa skott, nystart&quot;</li><li>&quot;Jag har gjort den här bilden förut&quot;</li><li>&quot;Lita på processen&quot;</li></ul><h3 id="omformuleringsovning" tabindex="-1">Omformuleringsövning <a class="header-anchor" href="#omformuleringsovning" aria-label="Permalink to &quot;Omformuleringsövning&quot;">​</a></h3><p>När du uppmärksammar din inre kritiker:</p><ol><li><strong>Paus</strong> - Identifiera den kritiska tanken</li><li><strong>Omformulera</strong> - Vad skulle din tränare säga?</li><li><strong>Återställ</strong> - Ta 3 andetag</li><li><strong>Omfokusera</strong> - Nästa bild</li></ol><hr><h2 id="praktiska-verktyg" tabindex="-1">Praktiska verktyg <a class="header-anchor" href="#praktiska-verktyg" aria-label="Permalink to &quot;Praktiska verktyg&quot;">​</a></h2><h3 id="_3-andetagsaterstallning" tabindex="-1">3-andetagsåterställning <a class="header-anchor" href="#_3-andetagsaterstallning" aria-label="Permalink to &quot;3-andetagsåterställning&quot;">​</a></h3><p>Använd detta efter misstag eller när du känner dig pressad:</p><ol><li><strong>Andning 1:</strong> Lägg märke till spänningen (var känner du den?)</li><li><strong>Andning 2:</strong> Släpp spänningen (släpp den)</li><li><strong>Andlag 3:</strong> Fokusera på nuet (denna bild, det här ögonblicket)</li></ol><h3 id="rutin-fore-skott" tabindex="-1">Rutin före skott <a class="header-anchor" href="#rutin-fore-skott" aria-label="Permalink to &quot;Rutin före skott&quot;">​</a></h3><p>Skapa konsekvens med en enkel rutin:</p><ol><li><strong>Visualisera</strong> - Se bilden för dig</li><li><strong>Andas</strong> - Ett djupt andetag</li><li><strong>Ankare</strong> - Rör vid din boule, känn tyngden</li><li><strong>Utför</strong> - Lita på och kasta</li></ol><h3 id="protokoll-for-felaterstallning" tabindex="-1">Protokoll för felåterställning <a class="header-anchor" href="#protokoll-for-felaterstallning" aria-label="Permalink to &quot;Protokoll för felåterställning&quot;">​</a></h3><p>Efter ett dåligt skott:</p><ol><li><strong>Erkänner</strong> - &quot;Det gick inte som planerat&quot;</li><li><strong>Släpp</strong> - Fysisk återställning (skaka av dig det, gå)</li><li><strong>Omfokusera</strong> - &quot;Nästa skott är en ny möjlighet&quot;</li><li><strong>Utför</strong> - Lita på din rutin</li></ol><hr><h2 id="din-handlingsplan" tabindex="-1">Din handlingsplan <a class="header-anchor" href="#din-handlingsplan" aria-label="Permalink to &quot;Din handlingsplan&quot;">​</a></h2><h3 id="denna-vecka" tabindex="-1">Denna vecka <a class="header-anchor" href="#denna-vecka" aria-label="Permalink to &quot;Denna vecka&quot;">​</a></h3><p>Välj EN teknik att öva på:</p><ul><li>[ ] 3-Andningsåterställning efter varje misstag</li><li>[ ] Förskottsrutin vid varje kast</li><li>[ ] Omformulera en Inre Kritiker-tanke per session</li><li>[ ] Öva på att växla från planerings- till utförandeläge</li></ul><h3 id="folj-dina-framsteg" tabindex="-1">Följ dina framsteg <a class="header-anchor" href="#folj-dina-framsteg" aria-label="Permalink to &quot;Följ dina framsteg&quot;">​</a></h3><p>Varsel:</p><ul><li>När känner du dig som mest i flow?</li><li>Vad triggar din inre kritiker?</li><li>Vilken teknik hjälper dig mest?</li><li>Hur förändras din prestation?</li></ul><hr><h2 id="resurser-och-nasta-steg" tabindex="-1">Resurser och nästa steg <a class="header-anchor" href="#resurser-och-nasta-steg" aria-label="Permalink to &quot;Resurser och nästa steg&quot;">​</a></h2><h3 id="fortsatt-lara" tabindex="-1">Fortsätt lära <a class="header-anchor" href="#fortsatt-lara" aria-label="Permalink to &quot;Fortsätt lära&quot;">​</a></h3><ul><li><strong>Zonen</strong> - Djupdykning i flödestillstånd</li><li><strong>Mental styrka</strong> - Avancerad presshantering</li><li><strong>Målmall</strong> - Strukturera din utveckling</li><li><strong>Mall för dagbok</strong> - Följ dina framsteg</li></ul><h3 id="ova-dagligen" tabindex="-1">Öva dagligen <a class="header-anchor" href="#ova-dagligen" aria-label="Permalink to &quot;Öva dagligen&quot;">​</a></h3><ul><li>5 minuter medveten andning</li><li>Visualisera lyckade bilder</li><li>Öva på din rutin före intag</li><li>Omformulera negativa tankar</li></ul><hr><h2 id="viktiga-slutsatser" tabindex="-1">Viktiga slutsatser <a class="header-anchor" href="#viktiga-slutsatser" aria-label="Permalink to &quot;Viktiga slutsatser&quot;">​</a></h2><ol><li><strong>Flödesstatus är tillgänglig</strong> - Du kan lära dig att ange det mer konsekvent</li><li><strong>Din inre röst spelar roll</strong> - Coacha dig själv, kritisera inte</li><li><strong>Enkla verktyg fungerar</strong> - 3 andetag, en rutin, en återställning</li><li><strong>Övning är nyckeln</strong> - Mentala färdigheter behöver träning, precis som tekniska färdigheter</li></ol><hr><p><strong>Kom ihåg:</strong> Mental träning handlar inte om positivt tänkande. Det handlar om praktiska tekniker som hjälper dig att prestera på bästa sätt under press.</p><hr><p><em>Besök carreau.app för fler resurser</em><em>Pétanque Academy - Elite Player Development</em></p>',61)])])}]]);export{n as __pageData,i as default};
